3    byte[] salt = new byte[16];
4    random.nextBytes(salt);
5    MessageDigest md = MessageDigest.getInstance("SHA-256");
6    md.update(salt);
7    byte[] hash = md.digest(password.getBytes());
8    // 솔트와 해시값을 함께 저장한다 (DB 설계서에 솔트 컬럼 정의)
9    return Base64.getEncoder().encodeToString(salt) + ":" + Base64.getEncoder().encodeToString(hash);
